const express = require('express');
const NodeCache = require('node-cache');
const bankingService = require('../services/banking');

const app = express();
app.use(express.json());
const mfaChallengeCache = new NodeCache({ stdTTL: 300 });

app.post('/api/transfers/verify-challenge', async (req, res) => {
  const { challengeId, otpCode } = req.body;

  // Retrieve pending wire transfer challenge from memory cache
  const challenge = mfaChallengeCache.get(challengeId);
  if (!challenge) {
    return res.status(400).json({ error: 'Challenge expired or invalid' });
  }

  // Ensure authenticated user initiated this challenge
  if (challenge.userId !== req.user.id) {
    return res.status(403).json({ error: 'Unauthorized challenge access' });
  }

  if (challenge.otpCode !== otpCode) {
    return res.status(401).json({ error: 'Invalid verification code' });
  }

  mfaChallengeCache.del(challengeId);
  const result = await bankingService.executeWireTransfer({
    fromAccount: challenge.sourceAccount,
    toAccount: challenge.destinationAccount,
    amount: challenge.amount
  });

  return res.json({ status: 'Transfer successful', transactionId: result.id });
});

module.exports = app;
